steps.script:
# Off by default; the three persistent layers exist and are hidden.
var to = tree.root.get_node("Main/BoardRoot/ThreatOverlay")
var names = []
for c in to.get_children():
	names.append(str(c.name))
if names != ["ShootFill", "ChargeFill", "Outlines"]:
	return "layers: %s" % str(names)
if to.activation_count != 0:
	return "activation_count %d at start" % to.activation_count
return "ok"

# Independent of ThreatOverlay: P2 (the Orks, active in this hot-seat game) is
# the viewer, so the enemy units are Player 1's units on the table (deployed,
# not embarked, with an alive placed model). The Caladius is in reserves.
var enemy = []
for uid in GameState.state.units:
	var u = GameState.state.units[uid]
	if int(u.owner) != 1:
		continue
	if int(u.status) == GameStateData.UnitStatus.UNDEPLOYED or int(u.status) == GameStateData.UnitStatus.IN_RESERVES:
		continue
	if u.get("embarked_in", null) != null:
		continue
	var placed = false
	for m in u.models:
		if m.get("alive", true) and m.get("position", null) != null:
			placed = true
	if placed:
		enemy.append(uid)
if enemy.size() != 8:
	return "fixture drift: %d P1 units on the table" % enemy.size()
var to = tree.root.get_node("Main/BoardRoot/ThreatOverlay")
if to.rendered_rings.size() != 2 * enemy.size():
	return "%d rings for %d enemy units" % [to.rendered_rings.size(), enemy.size()]
return "ok"

# Every shoot entry is MARGINAL_YELLOW, every charge entry INVALID_RED, and each
# enemy unit has exactly one of each; no friendly (P2) unit is painted.
var to = tree.root.get_node("Main/BoardRoot/ThreatOverlay")
var seen = {}
var bad = []
for r in to.rendered_rings:
	var uid = str(r.unit_id)
	if int(GameState.state.units[uid].owner) != 1:
		bad.append(uid + " is not an enemy unit")
	if r.kind == "shoot":
		if r.color_slot != "MARGINAL_YELLOW":
			bad.append(uid + " shoot slot " + str(r.color_slot))
	elif r.kind == "charge":
		if r.color_slot != "INVALID_RED":
			bad.append(uid + " charge slot " + str(r.color_slot))
	else:
		bad.append(uid + " kind " + str(r.kind))
	var key = uid + "/" + str(r.kind)
	if seen.has(key):
		bad.append("duplicate " + key)
	seen[key] = true
for r in to.rendered_rings:
	for k in ["shoot", "charge"]:
		if not seen.has(str(r.unit_id) + "/" + k):
			bad.append(str(r.unit_id) + " has no " + k + " entry")
return "ok" if bad.is_empty() else ", ".join(bad)

# Ranges are measured base edge to base edge (as the engine does): a ring's
# radius from a model's centre is range x 40 px + that model's base extent.
var to = tree.root.get_node("Main/BoardRoot/ThreatOverlay")
var ring = {}
for r in to.rendered_rings:
	ring[str(r.unit_id) + "/" + str(r.kind)] = r
var units = GameState.state.units
var bad = []
var want = {
	"U_SHIELD_CAPTAIN_A/charge": 12.0, "U_SHIELD_CAPTAIN_A/shoot": 12.0,
	"U_CONTEMPTOR-ACHILLUS_DREADNOUGHT_H/charge": 12.0, "U_CONTEMPTOR-ACHILLUS_DREADNOUGHT_H/shoot": 18.0,
	"U_TELEMON_HEAVY_DREADNOUGHT_I/shoot": 72.0, "U_CUSTODIAN_GUARD_B/shoot": 24.0,
	"U_CUSTODIAN_GUARD_B/charge": 12.0, "U_SHIELD_CAPTAIN_JETBIKE_A/shoot": 24.0,
}
for key in want:
	var uid = key.split("/")[0]
	var ext = 0.0
	for m in units[uid].models:
		ext = maxf(ext, Measurement.base_extent_px(m))
	var expect = want[key] * 40.0 + ext
	if not ring.has(key):
		bad.append(key + " missing")
	elif absf(float(ring[key].radius_px) - expect) > 0.5:
		bad.append("%s radius %.1f, want %.1f" % [key, float(ring[key].radius_px), expect])
	elif absf(float(ring[key].range_inches) - want[key]) > 0.01:
		bad.append("%s range %.1f, want %.1f" % [key, float(ring[key].range_inches), want[key]])
# The Blade Champion carries only melee weapons: no shooting threat at all.
var bc = ring.get("U_BLADE_CHAMPION_A/shoot", null)
if bc == null or float(bc.radius_px) != 0.0 or float(bc.range_inches) != 0.0:
	bad.append("melee-only Blade Champion got a shooting ring: " + str(bc))
return "ok" if bad.is_empty() else ", ".join(bad)

# Shown, with the doc's alphas on the two fill layers (the whole merged layer
# composites at that alpha, so overlaps never stack).
var to = tree.root.get_node("Main/BoardRoot/ThreatOverlay")
if not to.is_visible_in_tree():
	return "overlay not visible"
var sa = to.get_node("ShootFill").self_modulate.a
var ca = to.get_node("ChargeFill").self_modulate.a
if absf(sa - 0.15) > 0.001 or absf(ca - 0.10) > 0.001:
	return "fill alphas %.3f / %.3f" % [sa, ca]
if not (to.get_node("ShootFill") is CanvasGroup and to.get_node("ChargeFill") is CanvasGroup):
	return "fill layers are not CanvasGroups"
return "ok"

# Three more press/hold/release cycles: exactly one on/off per press (4 in all),
# nothing left on, and the same three layer nodes (no node churn).
var to = tree.root.get_node("Main/BoardRoot/ThreatOverlay")
var names = []
for c in to.get_children():
	names.append(str(c.name))
if names != ["ShootFill", "ChargeFill", "Outlines"]:
	return "layers: %s" % str(names)
if to.activation_count != 4:
	return "activation_count %d after 4 presses" % to.activation_count
if to.active or not to.rendered_rings.is_empty() or to.visible or to.is_tap_pending():
	return "still on after release"
return "ok"

# Key repeat while Tab is held: Tab echoes must be consumed, or each one reaches
# the GUI as ui_focus_next and hops the focus ring round the HUD.
var to = tree.root.get_node("Main/BoardRoot/ThreatOverlay")
if not to.active:
	return "overlay not on before the echo"
var btn = null
var stack = [tree.root.get_node("Main/HUD_Right")]
while not stack.is_empty() and btn == null:
	var n = stack.pop_front()
	if n is Button and n.is_visible_in_tree() and not n.disabled and n.focus_mode == Control.FOCUS_ALL:
		btn = n
	stack.append_array(n.get_children())
if btn == null:
	return "no focusable HUD button"
btn.grab_focus()
var vp = tree.root.get_viewport()
if vp.gui_get_focus_owner() != btn:
	return "could not focus " + str(btn.name)
var ev = InputEventKey.new()
ev.keycode = KEY_TAB
ev.physical_keycode = KEY_TAB
ev.pressed = true
ev.echo = true
Input.parse_input_event(ev)
Input.flush_buffered_events()
var focus_now = vp.gui_get_focus_owner()
if focus_now != null:
	focus_now.release_focus()
if focus_now != btn:
	return "echo moved focus from %s to %s" % [btn.name, str(focus_now.name) if focus_now != null else "null"]
if not to.active or to.activation_count != 5:
	return "echo changed the overlay: active=%s count=%d" % [str(to.active), to.activation_count]
return "ok"

# The tap cycled the shooter and never showed the overlay.
var to = tree.root.get_node("Main/BoardRoot/ThreatOverlay")
if to.activation_count != 5:
	return "tap turned the overlay on (activation_count %d)" % to.activation_count
if to.active or to.is_tap_pending():
	return "still on / pending after the tap"
return "ok"
